	{
		eventBus.register(itemIdResolver);
		eventBus.register(killCountTracker);
		overlayManager.add(collectionLogOverlay);
		localDropRateDatasetLoader.load();
		localRarityDatasetLoader.load();
		log.debug("Collection Log Popup Enhanced started!");
	}

	@Override
	protected void shutDown() throws Exception
	{
		eventBus.unregister(itemIdResolver);
		eventBus.unregister(killCountTracker);
		overlayManager.remove(collectionLogOverlay);
		collectionLogOverlay.clear();
		log.debug("Collection Log Popup Enhanced stopped!");
	}

	@Subscribe
	public void onChatMessage(ChatMessage chatMessage)
	{
		if (chatMessage.getType() != ChatMessageType.GAMEMESSAGE && chatMessage.getType() != ChatMessageType.SPAM)
		{
			return;
		}

		Matcher matcher = NEW_COLLECTION_LOG_ITEM.matcher(chatMessage.getMessage());
		if (matcher.matches())
		{
			String itemName = Text.removeTags(matcher.group(1));
			handleNewCollectionLogItem(null, itemName, null);
		}
	}

	@Subscribe
	public void onCommandExecuted(CommandExecuted commandExecuted)
	{
		if (!TEST_COMMAND.equalsIgnoreCase(commandExecuted.getCommand()))
		{
			return;
		}

		String[] args = commandExecuted.getArguments();
		if (args.length == 0)
		{
			testRandomDatasetItems(1);
			return;
		}

		if (args.length == 1)
		{
			try
			{
				int count = Integer.parseInt(args[0]);
				if (count <= 0)
				{
					log.debug("Count must be positive.");
					return;
				}
				testRandomDatasetItems(count);
				return;
			}
			catch (NumberFormatException e)
			{
				// Not a count - fall through and treat it as an item name instead.
			}
		}

		// A non-negative last token is a forced kill count; everything before it is the item name.
		Integer forcedKillCount = null;
		int nameArgCount = args.length;
		if (args.length >= 2)
		{
			try
			{
				int kc = Integer.parseInt(args[args.length - 1]);
				if (kc >= 0)
				{
					forcedKillCount = kc;
					nameArgCount = args.length - 1;
				}
			}
			catch (NumberFormatException e)
			{
				// Last token isn't a kill count - the whole thing is the item name.
			}
		}

		String itemName = String.join(" ", Arrays.copyOfRange(args, 0, nameArgCount));
		handleNewCollectionLogItem(null, itemName, forcedKillCount);
	}

	private void testRandomDatasetItems(int count)
	{
		List<Integer> itemIds = rarityResolver.randomItemIds(count);
		if (itemIds.isEmpty())
		{
			log.debug("No items available to test with - rarity dataset failed to load.");
			return;
		}
		if (itemIds.size() < count)
		{
			log.debug("Only {} distinct items available - showing all of them.", itemIds.size());
		}

		for (int itemId : itemIds)
		{
			int canonicalId = itemManager.canonicalize(itemId);
			String itemName = itemManager.getItemComposition(canonicalId).getName();
			handleNewCollectionLogItem(canonicalId, itemName, null);
		}
	}

	private void handleNewCollectionLogItem(Integer knownItemId, String itemName, Integer forcedKillCount)
	{
		if (knownItemId != null)
		{
			handleResolvedItem(knownItemId, itemName, "known", forcedKillCount);
			return;
		}

		// Resolution is asynchronous - see ItemIdResolver.resolveIdByName javadoc.
		itemIdResolver.resolveIdByName(itemName, (itemId, source) -> handleResolvedItem(itemId, itemName, source.toString(), forcedKillCount));
	}

	private void handleResolvedItem(int itemId, String itemName, String resolvedVia, Integer forcedKillCount)
	{
		RarityResult result = rarityResolver.resolve(itemId, itemName);

		Integer killCount;
		String source;
		if (forcedKillCount != null)
		{
			// Dev-only test override (see TEST_COMMAND) - bypasses the real correlated kill, so
			// there's no known source either.
			killCount = forcedKillCount;
			source = null;
		}
		else
		{
			// Read now, right before display, rather than when the chat message first arrived -
			// resolution can be deferred by a tick or more (see ItemIdResolver).
			KillCountTracker.RecentKill kill = killCountTracker.recentKill();

			killCount = kill != null ? kill.getKillCount() : null;
			source = kill != null ? kill.getSource() : null;
		}

		Double dropProbability = source != null
			? dropRateResolver.dropProbability(source, itemName)
			: dropRateResolver.dropProbabilityByItemName(itemName);
		// Without a known source, a drop from more than one tracked source has no single rate to show -
		// collect every candidate instead so the overlay can display them all (see CollectionLogOverlay).
		List<DropRateResolver.SourceRate> ambiguousDropRates = source == null && dropProbability == null
			? dropRateResolver.dropRatesByItemName(itemName)
			: List.of();

		log.debug("New collection log item '{}' (id {}, resolved via {}) resolved to {} (kill count {}, drop probability {}, ambiguous rates {})",
			itemName, itemId, resolvedVia, result, killCount, dropProbability, ambiguousDropRates);

		collectionLogOverlay.enqueue(itemName, result.getItemId(), result.getTier(), result.getPrice(), result.isHighAlch(),
			result.getAlchPrice(), result.getCompPercent(), killCount, dropProbability, ambiguousDropRates);
	}

	@Provides
	CollectionLogPopupEnhancedConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(CollectionLogPopupEnhancedConfig.class);
	}
}

package com.snakesteak.collectionlogpopupenhanced.rarity;

import com.google.gson.Gson;
import com.snakesteak.collectionlogpopupenhanced.CollectionLogPopupEnhancedConfig;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.Reader;
import java.util.Map;
import net.runelite.api.ItemComposition;
import net.runelite.client.game.ItemManager;
import org.junit.Assume;
import org.junit.Before;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.mockito.ArgumentMatchers.anyInt;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

/**
 * Expected percentiles/tiers below are derived by replaying the resolver's exact algorithm in a
 * throwaway script against the real dataset fixture below (1705 scored entries as of writing) -
 * see conversation history for the derivation. These aren't hand-picked to "look right"; they're
 * the actual output of the composite-score + percentile-rank math for these real dataset ids.
 *
 * The fixture is gitignored (see src/test/resources/local-only/README.md) - these tests are
 * skipped rather than failed if it isn't present locally.
 */
public class RarityResolverTest
{
	private static final String FIXTURE = "/local-only/collection-log.json";

	private ItemManager itemManager;
	private RarityResolver resolver;

	@Before
	public void before()
	{
		itemManager = mock(ItemManager.class);
		// Default: no high alch value either, so unstubbed items behave as price-0 like before the
		// high alch fallback was added. Individual tests override this per-id where needed.
		ItemComposition defaultComposition = mock(ItemComposition.class);
		when(itemManager.getItemComposition(anyInt())).thenReturn(defaultComposition);
		CollectionLogPopupEnhancedConfig config = new CollectionLogPopupEnhancedConfig()
		{
		};
		resolver = new RarityResolver(itemManager, config);
		resolver.reload(loadFixture());
	}

	private static Map<String, RarityResolver.CompletionEntry> loadFixture()
	{
		InputStream stream = RarityResolverTest.class.getResourceAsStream(FIXTURE);
		Assume.assumeTrue("Local fixture " + FIXTURE + " not present - see src/test/resources/local-only/README.md", stream != null);
		Gson gson = new Gson();
		try (Reader reader = new InputStreamReader(stream))
		{
			return gson.fromJson(reader, RarityResolver.DATASET_TYPE);
		}
		catch (Exception e)
		{
			throw new RuntimeException(e);
		}
	}

	@Test
	public void petNameWinsRegardlessOfIdOrPrice()
	{
		assertEquals(RarityTier.PET, resolver.resolve(11849, "Baby mole").getTier());
	}

	@Test
	public void petNameMatchIsCaseInsensitive()
	{
		assertEquals(RarityTier.PET, resolver.resolve(-1, "baby MOLE").getTier());
	}

	// Dataset id 20011: comp_percent 0, tied with 9 other items for the rarest slot in the whole
	// dataset -> percentile 100 under default (unstubbed = zero) prices.
	@Test
	public void tiedRarestCompPercentIsVeryRare()
	{
		assertEquals(RarityTier.VERY_RARE, resolver.resolve(20011, "Not a pet").getTier());
	}

	// Dataset id 22100: comp_percent 0.3 -> percentile ~97.8
	@Test
	public void veryLowCompPercentIsVeryRare()
	{
		assertEquals(RarityTier.VERY_RARE, resolver.resolve(22100, "Not a pet").getTier());
	}

	// Dataset id 4508: comp_percent 1.3 -> percentile ~90.0
	@Test
	public void lowCompPercentIsRare()
	{
		assertEquals(RarityTier.RARE, resolver.resolve(4508, "Not a pet").getTier());
	}

	// Dataset id 4068: comp_percent 4.3 -> percentile ~70.2
	@Test
	public void midCompPercentIsUncommon()
	{
		assertEquals(RarityTier.UNCOMMON, resolver.resolve(4068, "Not a pet").getTier());
	}

	// Dataset id 2615: comp_percent 10.9 -> percentile ~30.5
	@Test
	public void higherCompPercentIsCommon()
	{
		assertEquals(RarityTier.COMMON, resolver.resolve(2615, "Not a pet").getTier());
	}

	// Dataset id 11849: comp_percent 96.8, the unique highest (least rare) value in the dataset.
	@Test
	public void highestCompPercentInDatasetIsCommon()
	{
		assertEquals(RarityTier.COMMON, resolver.resolve(11849, "Not a pet").getTier());
	}

	@Test
	public void unknownItemFallsBackToValueScoreOnly()
	{
		// Synthetic, varying price per id so the value-score distribution isn't degenerate;
		// id 999999 lands on the max synthetic price (1000), so it should rank at the top
		// of the value-score-only distribution used when an item has no completion data.
		when(itemManager.getItemPrice(anyInt())).thenAnswer(invocation ->
		{
			int id = invocation.getArgument(0);
			return (id % 1000) + 1;
		});

		RarityResult result = resolver.resolve(999_999, "Brand new item");
		assertEquals(RarityTier.VERY_RARE, result.getTier());
		assertEquals(1000, result.getPrice());
	}

	// itemId -1 with completely unstubbed (all-zero) prices means there's no usable price signal
	// anywhere in the dataset - this must not be reported as VERY_RARE (that was the actual bug:
	// a fully degenerate/all-tied value-score distribution used to rank as the 100th percentile).
	@Test
	public void noUsablePriceSignalAnywhereDefaultsToCommonInsteadOfFalseVeryRare()
	{
		RarityResult result = resolver.resolve(-1, "Some untradeable unresolved item");
		assertEquals(RarityTier.COMMON, result.getTier());
	}

	@Test
	public void resultExposesCompPercentAndPriceForDisplay()
	{
		when(itemManager.getItemPrice(4508)).thenReturn(509);

		RarityResult result = resolver.resolve(4508, "Not a pet");
		assertEquals(Double.valueOf(1.3), result.getCompPercent());
		assertEquals(509, result.getPrice());
	}

	// Many collection log items have no GE price (untradeable, or tradeable but unlisted) but still
	// have a high alch value, which is a better rarity signal than reporting price 0.
	@Test
	public void fallsBackToHighAlchValueWhenNoGePrice()
	{
		when(itemManager.getItemPrice(4508)).thenReturn(0);
		ItemComposition composition = mock(ItemComposition.class);
		when(composition.getHaPrice()).thenReturn(1000);
		when(itemManager.getItemComposition(4508)).thenReturn(composition);

		RarityResult result = resolver.resolve(4508, "Not a pet");
		assertEquals(1000, result.getPrice());
		assertEquals(true, result.isHighAlch());
	}

	@Test
	public void doesNotFallBackToHighAlchWhenGePriceIsPositive()
	{
		when(itemManager.getItemPrice(4508)).thenReturn(509);
		ItemComposition composition = mock(ItemComposition.class);
		when(composition.getHaPrice()).thenReturn(1000);
		when(itemManager.getItemComposition(4508)).thenReturn(composition);

		RarityResult result = resolver.resolve(4508, "Not a pet");
		assertEquals(509, result.getPrice());
		assertEquals(false, result.isHighAlch());
	}

	@Test
	public void unresolvedItemIdDoesNotFallBackToHighAlch()
	{
		// itemId -1 must short-circuit to price 0 without ever calling getItemComposition(-1)
		RarityResult result = resolver.resolve(-1, "Some untradeable unresolved item");
		assertEquals(0, result.getPrice());
		assertEquals(false, result.isHighAlch());
	}

	// Regression test for the actual reported bug: ItemManager.getItemPrice() sums mapped/bundled item
	// prices with plain int arithmetic and can overflow to a negative number for at least one item.
	// Math.log(negative) is NaN, which used to poison the shared logPriceMin/logPriceMax (Math.min/max
	// propagate NaN forever once it appears) - after that, EVERY item's value score came out NaN, and
	// Arrays.binarySearch treats NaN as "greater than everything", so every single item rated as the
	// 100th percentile regardless of its actual comp% or price. Dataset id 2583 is an arbitrary stand-in
	// for "the one poisoned entry" here; id 11849 (comp 96.8%, the dataset's least-rare item) is the
	// control - it must still come back COMMON even with a NaN-inducing price elsewhere in the dataset.
	@Test
	public void negativePriceOnOneDatasetItemDoesNotPoisonEveryoneElsesPercentile()
	{
		when(itemManager.getItemPrice(2583)).thenReturn(-2);

		RarityResult result = resolver.resolve(11849, "Not a pet");
		assertEquals(RarityTier.COMMON, result.getTier());
	}

	// Same failure mode, but from the other side of the overflow: a price at/near Integer.MAX_VALUE
	// wraps back to negative when "+1" is done in int arithmetic (2147483647 + 1 == Integer.MIN_VALUE),
	// which still feeds Math.log() a negative number -> NaN -> same dataset-wide poisoning as above.
	@Test
	public void maxIntPriceOnOneDatasetItemDoesNotPoisonEveryoneElsesPercentile()
	{
		when(itemManager.getItemPrice(2583)).thenReturn(Integer.MAX_VALUE);

		RarityResult result = resolver.resolve(11849, "Not a pet");
		assertEquals(RarityTier.COMMON, result.getTier());
	}

	// Reported live: an item with NO completion data at all (compPercent null) still came back
	// VERY_RARE with logPriceMin/logPriceMax both NaN - proving the poisoning happens in buildDataset()
	// itself (shared across every resolve() call), not just in the compPercent-known branch.
	@Test
	public void unknownItemStillResolvesSanelyWhenSomeDatasetPriceOverflows()
	{
		when(itemManager.getItemPrice(2583)).thenReturn(Integer.MAX_VALUE);

		RarityResult result = resolver.resolve(-1, "Cupric sulfate (Members)");
		assertEquals(RarityTier.COMMON, result.getTier());
	}
}

package com.snakesteak.collectionlogpopupenhanced.rarity;

import com.google.gson.Gson;
import com.snakesteak.collectionlogpopupenhanced.CollectionLogPopupEnhancedConfig;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.Reader;
import java.util.Collections;
import java.util.List;
import java.util.Map;
import net.runelite.api.Client;
import net.runelite.api.Item;
import net.runelite.api.ItemComposition;
import net.runelite.api.ItemContainer;
import net.runelite.api.TileItem;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.ItemContainerChanged;
import net.runelite.api.events.ItemDespawned;
import net.runelite.api.events.ItemSpawned;
import net.runelite.api.gameval.InventoryID;
import net.runelite.client.game.ItemManager;
import net.runelite.http.api.item.ItemPrice;
import org.junit.Assume;
import org.junit.Before;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

/**
 * The pet-resolution test below needs the real collection-log.json fixture (see
 * src/test/resources/local-only/README.md, gitignored) - all tests in this class are skipped
 * rather than failed if it isn't present locally.
 */
public class ItemIdResolverTest
{
	private static final String FIXTURE = "/local-only/collection-log.json";

	private Client client;
	private ItemManager itemManager;
	private ItemIdResolver resolver;

	private static Map<String, RarityResolver.CompletionEntry> loadFixture()
	{
		InputStream stream = ItemIdResolverTest.class.getResourceAsStream(FIXTURE);
		Assume.assumeTrue("Local fixture " + FIXTURE + " not present - see src/test/resources/local-only/README.md", stream != null);
		Gson gson = new Gson();
		try (Reader reader = new InputStreamReader(stream))
		{
			return gson.fromJson(reader, RarityResolver.DATASET_TYPE);
		}
		catch (Exception e)
		{
			throw new RuntimeException(e);
		}
	}

	private static ItemPrice itemPrice(int id, String name)
	{
		ItemPrice itemPrice = new ItemPrice();
		itemPrice.setId(id);
		itemPrice.setName(name);
		return itemPrice;
	}

	private static void nameItem(ItemManager itemManager, int id, String name)
	{
		ItemComposition composition = mock(ItemComposition.class);
		when(composition.getName()).thenReturn(name);
		when(itemManager.getItemComposition(id)).thenReturn(composition);
	}

	private static ItemContainer inventoryOf(Item... items)
	{
		ItemContainer inventory = mock(ItemContainer.class);
		when(inventory.getItems()).thenReturn(items);
		return inventory;
	}

	/**
	 * Captures the id/source delivered to a ResolveCallback so tests can assert on it after the fact.
	 * Resolution is asynchronous now (see ItemIdResolver.resolveIdByName), so tests can't just take a
	 * return value.
	 */
	private static class CapturingCallback implements ItemIdResolver.ResolveCallback
	{
		private boolean called;
		private int value;
		private ItemIdResolver.Source source;

		@Override
		public void accept(int value, ItemIdResolver.Source source)
		{
			this.called = true;
			this.value = value;
			this.source = source;
		}
	}

	@Before
	public void before()
	{
		client = mock(Client.class);
		itemManager = mock(ItemManager.class);
		CollectionLogPopupEnhancedConfig config = new CollectionLogPopupEnhancedConfig()
		{
		};
		RarityResolver rarityResolver = new RarityResolver(itemManager, config);
		rarityResolver.reload(loadFixture());
		resolver = new ItemIdResolver(client, itemManager, rarityResolver);

		ItemContainer emptyInventory = inventoryOf();
		when(client.getItemContainer(InventoryID.INV)).thenReturn(emptyInventory);
		when(itemManager.search(org.mockito.ArgumentMatchers.anyString())).thenReturn(Collections.emptyList());
	}

	@Test
	public void resolvesPetByNameWithoutTouchingInventoryOrGround()
	{
		CapturingCallback callback = new CapturingCallback();
		resolver.resolveIdByName("Baby mole", callback);

		assertEquals(net.runelite.api.gameval.ItemID.MOLEPET, callback.value);
		assertEquals(ItemIdResolver.Source.PET, callback.source);
	}

	@Test
	public void findsMatchInInventorySynchronously()
	{
		ItemContainer inventory = inventoryOf(new Item(100, 1), new Item(-1, 0));
		when(client.getItemContainer(InventoryID.INV)).thenReturn(inventory);
		nameItem(itemManager, 100, "Foo");

		CapturingCallback callback = new CapturingCallback();
		resolver.resolveIdByName("Foo", callback);

		assertEquals(100, callback.value);
		assertEquals(ItemIdResolver.Source.INVENTORY, callback.source);
	}

	@Test
	public void findsMatchAmongTrackedGroundItemsSynchronously()
	{
		TileItem tileItem = mock(TileItem.class);
		when(tileItem.getId()).thenReturn(200);
		nameItem(itemManager, 200, "Bar");

		resolver.onItemSpawned(new ItemSpawned(null, tileItem));

		CapturingCallback callback = new CapturingCallback();
		resolver.resolveIdByName("Bar", callback);

		assertEquals(200, callback.value);
		assertEquals(ItemIdResolver.Source.GROUND, callback.source);
	}

	@Test
	public void despawnedGroundItemNoLongerMatches()
	{
		TileItem tileItem = mock(TileItem.class);
		when(tileItem.getId()).thenReturn(201);
		nameItem(itemManager, 201, "Baz");

		resolver.onItemSpawned(new ItemSpawned(null, tileItem));
		resolver.onItemDespawned(new ItemDespawned(null, tileItem));

		CapturingCallback callback = new CapturingCallback();
		resolver.resolveIdByName("Baz", callback);
		assertFalse("should defer rather than resolve immediately", callback.called);

		resolver.onGameTick(new GameTick());
		assertEquals(-1, callback.value);
		assertEquals(ItemIdResolver.Source.UNRESOLVED, callback.source);
	}

	@Test
	public void fallsBackToGeSearchAtEndOfTickWhenNotInInventoryOrOnGround()
	{
		when(itemManager.search("Twisted bow")).thenReturn(List.of(itemPrice(20997, "Twisted bow")));

		CapturingCallback callback = new CapturingCallback();
		resolver.resolveIdByName("Twisted bow", callback);
		assertFalse("should defer rather than resolve immediately", callback.called);

		resolver.onGameTick(new GameTick());
		assertEquals(20997, callback.value);
		assertEquals(ItemIdResolver.Source.GE_SEARCH, callback.source);
	}

	@Test
	public void returnsMinusOneWhenNothingMatchesByEndOfTick()
	{
		CapturingCallback callback = new CapturingCallback();
		resolver.resolveIdByName("Nothing matches this", callback);

		resolver.onGameTick(new GameTick());
		assertEquals(-1, callback.value);
		assertEquals(ItemIdResolver.Source.UNRESOLVED, callback.source);
	}

	/**
	 * Reproduces the real-world bug: the "New item added to your collection log" chat message is
	 * delivered BEFORE the ItemContainerChanged event that actually adds the item to the inventory.
	 * A purely synchronous inventory/ground/GE check (the old behavior) can never find an untradeable
	 * item in this case and always falls back to -1. The resolver must wait for the inventory update
	 * and diff it against the pre-message snapshot to find the newly-appeared id.
	 */
	@Test
	public void resolvesUntradeableItemFromDeferredInventoryDiff()
	{
		nameItem(itemManager, 300, "Partial note");

		CapturingCallback callback = new CapturingCallback();
		resolver.resolveIdByName("Partial note", callback);
		assertFalse("id shouldn't be known yet - inventory hasn't updated", callback.called);

		ItemContainer updatedInventory = inventoryOf(new Item(300, 1));
		resolver.onItemContainerChanged(new ItemContainerChanged(InventoryID.INV, updatedInventory));

		assertEquals(300, callback.value);
		assertEquals(ItemIdResolver.Source.INVENTORY_DIFF, callback.source);
	}

	@Test
	public void ignoresItemContainerChangedForOtherContainers()
	{
		nameItem(itemManager, 300, "Partial note");

		CapturingCallback callback = new CapturingCallback();
		resolver.resolveIdByName("Partial note", callback);

		ItemContainer bank = inventoryOf(new Item(300, 1));
		resolver.onItemContainerChanged(new ItemContainerChanged(InventoryID.BANK, bank));
		assertFalse("bank updates shouldn't resolve an inventory-bound lookup", callback.called);

		resolver.onGameTick(new GameTick());
		assertEquals(-1, callback.value);
		assertEquals(ItemIdResolver.Source.UNRESOLVED, callback.source);
	}
}

package com.snakesteak.collectionlogpopupenhanced.droprate;

import com.google.gson.Gson;
import java.io.InputStream;
import java.io.InputStreamReader;
