@Slf4j
public class SuperiorSlayerTrackerPanel extends PluginPanel
{
	private static final int ICON_SIZE = 16;
	/** RuneLite ProgressBar paints its fill with this hardcoded height. */
	private static final int STOCK_PAINT_HEIGHT = 16;
	/** Stock 16px bar height + 20%; FullHeightProgressBar extends the fill to match. */
	private static final int PROGRESS_HEIGHT = 19;
	private static final int ROW_HEIGHT = PROGRESS_HEIGHT;

	private final SuperiorKillStorage killStorage;
	private final SuperiorSlayerTrackerConfig config;
	private final Client client;
	private final LootTrackerImportService lootTrackerImportService;

	@Setter
	private ArrayList<SuperiorKill> killList = new ArrayList<>();

	@Setter
	private boolean loaded = false;

	/**
	 * ProgressBar hardcodes its fill to the top 16px, so a taller bar would show
	 * an unfilled strip at the bottom. Extend the fill to the full height and
	 * redraw the labels so their descenders aren't painted over.
	 */
	private static class FullHeightProgressBar extends ProgressBar
	{
		@Override
		public void paint(Graphics g)
		{
			super.paint(g);

			final int height = getHeight();
			if (height <= STOCK_PAINT_HEIGHT)
			{
				return;
			}

			final int fillWidth = (int) (getWidth() * (getPercentage() / 100f));
			g.setColor(getForeground());
			g.fillRect(0, STOCK_PAINT_HEIGHT, fillWidth, height - STOCK_PAINT_HEIGHT);
			super.paintComponents(g);
		}
	}

	private final JPanel contentPanel = new JPanel();
	private final Map<SuperiorMonster, ImageIcon> iconCache = new EnumMap<>(SuperiorMonster.class);
	private JButton syncButton;

	public SuperiorSlayerTrackerPanel(
		final SuperiorKillStorage killStorage,
		final SuperiorSlayerTrackerConfig config,
		final Client client,
		final LootTrackerImportService lootTrackerImportService
	)
	{
		this.killStorage = killStorage;
		this.config = config;
		this.client = client;
		this.lootTrackerImportService = lootTrackerImportService;

		contentPanel.setBackground(ColorScheme.DARK_GRAY_COLOR);
		contentPanel.setLayout(new BoxLayout(contentPanel, BoxLayout.Y_AXIS));
		// PluginPanel uses DynamicGridLayout; BorderLayout constraints are ignored.
		add(contentPanel);
		updateView();
	}

	public void loadKillList()
	{
		if (!killStorage.isReady())
		{
			return;
		}

		killList = killStorage.loadKills();
		loaded = true;
		log.info("Superior Slayer Tracker panel refreshed with {} kills", killList.size());
		updateView();
	}

	public void addKill(SuperiorKill kill)
	{
		killList.add(kill);
		updateView();
	}

	public void updateView()
	{
		contentPanel.removeAll();

		if (config.showTitle())
		{
			JLabel title = new JLabel("Superior Slayer Tracker");
			title.setFont(FontManager.getRunescapeBoldFont());
			title.setForeground(ColorScheme.BRAND_ORANGE);
			title.setBorder(new EmptyBorder(0, 0, 6, 0));
			title.setAlignmentX(LEFT_ALIGNMENT);
			contentPanel.add(title);
		}

		contentPanel.add(buildKillTable());
		contentPanel.add(Box.createVerticalStrut(6));
		contentPanel.add(buildActionButtons());
		// Extra space so the last row isn't clipped by the scroll viewport edge.
		contentPanel.add(Box.createVerticalStrut(12));

		contentPanel.revalidate();
		contentPanel.repaint();
	}

	private JPanel buildActionButtons()
	{
		JPanel row = new JPanel(new GridLayout(1, 2, 4, 0));
		row.setBackground(ColorScheme.DARK_GRAY_COLOR);
		row.setAlignmentX(LEFT_ALIGNMENT);
		row.setMaximumSize(new Dimension(Integer.MAX_VALUE, 28));
		row.setPreferredSize(new Dimension(PluginPanel.PANEL_WIDTH, 28));

		syncButton = new JButton("Sync Superiors");
		syncButton.setFont(FontManager.getRunescapeSmallFont());
		refreshSyncButtonState();
		syncButton.addActionListener(e -> onSyncClicked());

		JButton clearButton = new JButton("Clear data");
		clearButton.setFont(FontManager.getRunescapeSmallFont());
		clearButton.setToolTipText("Delete all logged superior kills and re-enable Sync Superiors.");
		clearButton.addActionListener(e -> onClearClicked());

		row.add(syncButton);
		row.add(clearButton);
		return row;
	}

	private void refreshSyncButtonState()
	{
		if (syncButton == null)
		{
			return;
		}

		// Username can be briefly unset around login; GameState is the reliable gate.
		if (client.getGameState() != GameState.LOGGED_IN)
		{
			syncButton.setEnabled(false);
			syncButton.setToolTipText("Log in to import superior kills from Loot Tracker.");
			return;
		}

		if (lootTrackerImportService.isImportDone())
		{
			syncButton.setEnabled(false);
			syncButton.setToolTipText("Already synced. Clear data to sync again.");
			return;
		}

		syncButton.setEnabled(true);
		syncButton.setToolTipText(
			"One-time import of superior kill counts from RuneLite Loot Tracker. "
				+ "Timestamps/modifiers unknown; loot is not reconstructed."
		);
	}

	private void onSyncClicked()
	{
		if (lootTrackerImportService.isImportDone())
		{
			refreshSyncButtonState();
			return;
		}

		final int written = lootTrackerImportService.importFromLootTracker();
		if (written < 0)
		{
			JOptionPane.showMessageDialog(
				this,
				"Could not sync. Make sure you are logged in.",
				"Sync Superiors",
				JOptionPane.WARNING_MESSAGE
			);
			refreshSyncButtonState();
			return;
		}

		loadKillList();
		JOptionPane.showMessageDialog(
			this,
			written == 0
				? "Sync complete. No new superior kills to import."
				: "Sync complete. Imported " + written + " superior kill(s).",
			"Sync Superiors",
			JOptionPane.INFORMATION_MESSAGE
		);
	}

	private void onClearClicked()
	{
		final int confirm = JOptionPane.showConfirmDialog(
			this,
			"Delete all superior kills in this plugin's log?\n\n"
				+ "This also re-enables Sync Superiors.\n"
				+ "Warning: Mortimer superior unique modifiers saved on those kills will be lost.",
			"Clear data",
			JOptionPane.YES_NO_OPTION,
			JOptionPane.WARNING_MESSAGE
		);
		if (confirm != JOptionPane.YES_OPTION)
		{
			return;
		}

		if (!killStorage.isReady())
		{
			JOptionPane.showMessageDialog(
				this,
				"Could not clear data (profile not ready).",
				"Clear data",
				JOptionPane.WARNING_MESSAGE
			);
			return;
		}

		killStorage.clearKills();
		lootTrackerImportService.resetImportState();
		killList = new ArrayList<>();
		loaded = true;
		updateView();
	}

	private JPanel buildKillTable()
	{
		JPanel wrapper = new JPanel();
		wrapper.setLayout(new BoxLayout(wrapper, BoxLayout.Y_AXIS));
		wrapper.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		wrapper.setBorder(new EmptyBorder(4, 4, 8, 4));
		wrapper.setAlignmentX(LEFT_ALIGNMENT);
		wrapper.setMaximumSize(new Dimension(Integer.MAX_VALUE, Integer.MAX_VALUE));

		Map<SuperiorMonster, Integer> counts = countKillsByMonster();
		Map<SuperiorMonster, Integer> hearts = countHeartsByMonster();
		Map<SuperiorMonster, Double> effectiveWeights = effectiveWeightsByMonster();
		List<Map.Entry<SuperiorMonster, Integer>> rows = new ArrayList<>();

		for (Map.Entry<SuperiorMonster, Integer> entry : counts.entrySet())
		{
			if (config.showOnlyKilled() && entry.getValue() <= 0)
			{
				continue;
			}
			rows.add(entry);
		}
		// Most heart progress first; tie-break on kill count for equal-progress rows.
		rows.sort((a, b) ->
		{
			int byProgress = Double.compare(
				heartProgressFraction(b.getKey(), effectiveWeights),
				heartProgressFraction(a.getKey(), effectiveWeights)
			);
			return byProgress != 0 ? byProgress : Integer.compare(b.getValue(), a.getValue());
		});

		int total = 0;
		int totalHearts = 0;
		double expectedHearts = 0;
		for (Map.Entry<SuperiorMonster, Integer> entry : rows)
		{
			SuperiorMonster monster = entry.getKey();
			int kills = entry.getValue();
			total += kills;
			totalHearts += hearts.getOrDefault(monster, 0);
			expectedHearts += effectiveWeights.getOrDefault(monster, 0d)
				/ monster.getHeartRarityDenominator();
		}

		wrapper.add(buildTotalKillsRow(total));
		wrapper.add(Box.createVerticalStrut(4));

		if (rows.isEmpty())
		{
			JLabel empty = new JLabel(loaded ? "No superior kills logged yet." : "Log in to load kill data.");
			empty.setFont(FontManager.getRunescapeSmallFont());
			empty.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
			empty.setAlignmentX(LEFT_ALIGNMENT);
			wrapper.add(empty);
			return wrapper;
		}

		for (Map.Entry<SuperiorMonster, Integer> entry : rows)
		{
			SuperiorMonster monster = entry.getKey();
			int kills = entry.getValue();
			double effectiveWeight = effectiveWeights.getOrDefault(monster, (double) kills);

			JPanel row = buildMonsterRow(
				monster,
				kills,
				effectiveWeight,
				hearts.getOrDefault(monster, 0)
			);
			row.setAlignmentX(LEFT_ALIGNMENT);
			wrapper.add(row);
			wrapper.add(Box.createVerticalStrut(2));
		}

		wrapper.add(Box.createVerticalStrut(6));
		wrapper.add(buildOverallHeartProgress(totalHearts, expectedHearts));

		return wrapper;
	}

	private JPanel buildTotalKillsRow(int totalKills)
	{
		JPanel row = new JPanel(new BorderLayout());
		row.setBackground(ColorScheme.DARK_GRAY_COLOR);
		row.setBorder(new EmptyBorder(4, 6, 4, 6));
		row.setAlignmentX(LEFT_ALIGNMENT);
		row.setMaximumSize(new Dimension(Integer.MAX_VALUE, 24));

		JLabel title = new JLabel("Superior kills");
		title.setFont(FontManager.getRunescapeSmallFont());
		title.setForeground(ColorScheme.LIGHT_GRAY_COLOR);

		JLabel total = new JLabel(String.valueOf(totalKills));
		total.setFont(FontManager.getRunescapeSmallFont());
		total.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		total.setHorizontalAlignment(SwingConstants.RIGHT);
		total.setToolTipText("Total superior kills logged");

		row.add(title, BorderLayout.WEST);
		row.add(total, BorderLayout.EAST);
		return row;
	}

	private ProgressBar buildOverallHeartProgress(int heartsReceived, double expectedHearts)
	{
		// Progress toward the next expected heart: expected − received.
		// Label can exceed 100% (e.g. 126%); visual fill still caps at full.
		final double towardNext = Math.max(0d, expectedHearts - heartsReceived);
		final int percent = (int) Math.round(towardNext * 100d);

		ProgressBar bar = new FullHeightProgressBar();
		bar.setMaximumValue(100);
		bar.setValue(Math.min(percent, 100));
		bar.setLeftLabel(heartsReceived + (heartsReceived == 1 ? " heart" : " hearts"));
		bar.setCenterLabel(percent + "%");
		bar.setRightLabel(String.format("%.2f exp", expectedHearts));
		bar.setPreferredSize(new Dimension(PluginPanel.PANEL_WIDTH, PROGRESS_HEIGHT));
		bar.setMinimumSize(new Dimension(60, PROGRESS_HEIGHT));
		bar.setMaximumSize(new Dimension(Integer.MAX_VALUE, PROGRESS_HEIGHT));
		bar.setAlignmentX(LEFT_ALIGNMENT);
		bar.setBackground(ColorScheme.DARK_GRAY_COLOR);
		bar.setForeground(overallProgressColor(percent, heartsReceived, expectedHearts));
		bar.setToolTipText(String.format(
			"Overall progress toward an imbued heart based on kill rates "
				+ "(including Mortimer superior-unique modifiers).%n"
				+ "Hearts received: %d%n"
				+ "Expected hearts: %.2f",
			heartsReceived,
			expectedHearts
		));
		return bar;
	}

	private static Color overallProgressColor(int percent, int heartsReceived, double expectedHearts)
	{
		if (heartsReceived > 0 && expectedHearts <= heartsReceived)
		{
			return ColorScheme.PROGRESS_COMPLETE_COLOR;
		}
		if (percent >= 100)
		{
			return ColorScheme.PROGRESS_ERROR_COLOR;
		}
		return ColorScheme.PROGRESS_INPROGRESS_COLOR;
	}

	private JPanel buildMonsterRow(SuperiorMonster monster, int kills, double effectiveWeight, int hearts)
	{
		JPanel row = new JPanel(new BorderLayout(4, 0));
		row.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		// Keep preferred/max in sync so BoxLayout does not under-report total height
		// (which clips the last row in the PluginPanel scroll viewport).
		final Dimension rowSize = new Dimension(PluginPanel.PANEL_WIDTH, ROW_HEIGHT);
		row.setPreferredSize(rowSize);
		row.setMinimumSize(rowSize);
		row.setMaximumSize(new Dimension(Integer.MAX_VALUE, ROW_HEIGHT));

		JLabel icon = monsterIconCell(monster);
		row.add(icon, BorderLayout.WEST);
		row.add(buildHeartProgressBar(monster, kills, effectiveWeight, hearts), BorderLayout.CENTER);
		return row;
	}

	private ProgressBar buildHeartProgressBar(
		SuperiorMonster monster,
		int kills,
		double effectiveWeight,
		int hearts
	)
	{
		int rate = monster.getHeartRarityDenominator();
		// Label can exceed 100% (e.g. 126%); visual fill still caps at full.
		int percent = rate == 0 ? 0 : (int) Math.round((effectiveWeight * 100d) / rate);
		// ProgressBar is int-based; scale by 100 so fractional Mortimer weights still fill LTR.
		int maxScaled = Math.max(rate, 1) * 100;
		int valueScaled = (int) Math.round(Math.min(effectiveWeight, rate) * 100d);

		ProgressBar bar = new FullHeightProgressBar();
		bar.setMaximumValue(maxScaled);
		bar.setValue(valueScaled);
		bar.setLeftLabel(String.valueOf(kills));
		bar.setCenterLabel(percent + "%");
		bar.setRightLabel("1/" + rate);
		bar.setPreferredSize(new Dimension(100, PROGRESS_HEIGHT));
		bar.setMinimumSize(new Dimension(60, PROGRESS_HEIGHT));
		bar.setBackground(ColorScheme.DARK_GRAY_COLOR);
		bar.setForeground(progressColor(effectiveWeight, rate, hearts));
		bar.setToolTipText(String.format(
			"%s — %d kills (%.2f effective) / %d toward imbued heart (1/%d)%s",
			monster.getDisplayName(),
			kills,
			effectiveWeight,
			rate,
			rate,
			hearts > 0 ? " · Hearts: " + hearts : ""
		));
		return bar;
	}

	private static Color progressColor(double effectiveWeight, int rate, int hearts)
	{
		if (hearts > 0)
		{
			return ColorScheme.PROGRESS_COMPLETE_COLOR;
		}
		if (effectiveWeight >= rate)
		{
			return ColorScheme.PROGRESS_ERROR_COLOR;
		}
		return ColorScheme.PROGRESS_INPROGRESS_COLOR;
	}

	/** Progress toward a heart as a fraction (matches the percent shown on each row's bar). */
	private static double heartProgressFraction(SuperiorMonster monster, Map<SuperiorMonster, Double> effectiveWeights)
	{
		final int rate = monster.getHeartRarityDenominator();
		return rate == 0 ? 0d : effectiveWeights.getOrDefault(monster, 0d) / rate;
	}

	private Map<SuperiorMonster, Integer> countKillsByMonster()
	{
		Map<SuperiorMonster, Integer> counts = new LinkedHashMap<>();
		for (SuperiorMonster monster : SuperiorMonster.values())
		{
			counts.put(monster, 0);
		}

		for (SuperiorKill kill : killList)
		{
			SuperiorMonster monster = SuperiorMonster.fromNpcName(kill.getMonsterName());
			if (monster == null)
			{
				continue;
			}
			counts.put(monster, counts.get(monster) + 1);
		}

		return counts;
	}

	private Map<SuperiorMonster, Double> effectiveWeightsByMonster()
	{
		Map<SuperiorMonster, Double> weights = new EnumMap<>(SuperiorMonster.class);
		for (SuperiorMonster monster : SuperiorMonster.values())
		{
			weights.put(monster, 0d);
		}

		for (SuperiorKill kill : killList)
		{
			SuperiorMonster monster = SuperiorMonster.fromNpcName(kill.getMonsterName());
			if (monster == null)
			{
				continue;
			}
			weights.put(
				monster,
				weights.get(monster) + HeartExpectation.effectiveKillWeight(kill.getSuperiorDropRateModifier())
			);
		}

		return weights;
	}

	private Map<SuperiorMonster, Integer> countHeartsByMonster()
	{
		Map<SuperiorMonster, Integer> hearts = new EnumMap<>(SuperiorMonster.class);
		for (SuperiorMonster monster : SuperiorMonster.values())
		{
			hearts.put(monster, 0);
		}

		for (SuperiorKill kill : killList)
		{
			if (!kill.isImbuedHeart())
			{
				continue;
			}
			SuperiorMonster monster = SuperiorMonster.fromNpcName(kill.getMonsterName());
			if (monster == null)
			{
				continue;
			}
			hearts.put(monster, hearts.get(monster) + 1);
		}

		return hearts;
	}

	private JLabel monsterIconCell(SuperiorMonster monster)
	{
		JLabel icon = new JLabel();
		icon.setHorizontalAlignment(SwingConstants.CENTER);
		icon.setPreferredSize(new Dimension(ICON_SIZE + 2, ROW_HEIGHT));
		icon.setMinimumSize(new Dimension(ICON_SIZE + 2, ROW_HEIGHT));
		icon.setMaximumSize(new Dimension(ICON_SIZE + 2, ROW_HEIGHT));
		icon.setToolTipText(monster.getDisplayName());
		icon.setIcon(getMonsterIcon(monster));
		return icon;
	}

	private ImageIcon getMonsterIcon(SuperiorMonster monster)
	{
		return iconCache.computeIfAbsent(monster, key ->
		{
			try
			{
				BufferedImage image = ImageUtil.loadImageResource(
					com.superiorslayertracker.SuperiorSlayerTrackerPlugin.class,
					key.getIconResourcePath()
				);
				return scaleIcon(image);
			}
			catch (IllegalArgumentException e)
			{
				log.warn("Missing icon for {}: {}", key.getDisplayName(), key.getIconResourcePath());
				BufferedImage placeholder = new BufferedImage(ICON_SIZE, ICON_SIZE, BufferedImage.TYPE_INT_ARGB);
				return new ImageIcon(placeholder);
			}
		});
	}

	private ImageIcon scaleIcon(BufferedImage image)
	{
		Image scaled = image.getScaledInstance(ICON_SIZE, ICON_SIZE, Image.SCALE_SMOOTH);
		return new ImageIcon(scaled);
	}
}

package com.superiorslayertracker;

import java.util.ArrayList;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

/**
 * Pure parsing helpers for Mortimer task-choice / assignment modifier text.
 */
final class TaskModifierParser
{
	static final Pattern SUPERIOR_UNIQUE_BONUS = Pattern.compile(
		"(?i)\\+?(\\d+)\\s*%\\s*Superior unique chance");

	private static final Pattern NEW_TASK = Pattern.compile(
		"(?i)Your new task is to kill\\s+(\\d+)\\s+(.+?)(?:\\.|(?=Completing)|$)");

	private TaskModifierParser()
	{
	}

	static Integer parseSuperiorUniqueBonus(String text)
	{
		if (text == null || text.isEmpty())
		{
			return null;
		}

		final Matcher matcher = SUPERIOR_UNIQUE_BONUS.matcher(text);
		if (!matcher.find())
		{
			return null;
		}

		return Integer.parseInt(matcher.group(1));
	}

	static String parseAssignedTaskName(String text)
	{
		if (text == null || text.isEmpty())
		{
			return null;
		}

		final Matcher matcher = NEW_TASK.matcher(text.replace('\n', ' '));
		if (!matcher.find())
		{
			return null;
		}

		return matcher.group(2).trim();
	}

	/**
	 * Walk ordered widget texts from the Slayer Task Choice UI and map creature
	 * names to superior-unique bonuses when present on that offer.
	 */
	static Map<String, Integer> parseChoiceOffers(List<String> texts)
	{
		if (texts == null || texts.isEmpty())
		{
			return Collections.emptyMap();
		}

		final Map<String, Integer> offers = new LinkedHashMap<>();
		String lastCreature = null;

		for (String raw : texts)
		{
			if (raw == null)
			{
				continue;
			}

			final String text = raw.trim();
			if (text.isEmpty())
			{
				continue;
			}

			final Integer bonus = parseSuperiorUniqueBonus(text);
			if (bonus != null)
			{
				if (lastCreature != null)
				{
					offers.put(normalizeTaskKey(lastCreature), bonus);
				}
				continue;
			}

			if (isIgnorableChoiceText(text))
			{
				continue;
			}

			if (looksLikeCreatureName(text))
			{
				lastCreature = text;
			}
		}

		return offers;
	}

	static Integer lookupOffer(Map<String, Integer> offers, String taskName)
	{
		if (offers == null || offers.isEmpty() || taskName == null || taskName.isEmpty())
		{
			return null;
		}

		final String key = normalizeTaskKey(taskName);
		final Integer exact = offers.get(key);
		if (exact != null)
		{
			return exact;
		}

		for (Map.Entry<String, Integer> entry : offers.entrySet())
		{
			if (key.contains(entry.getKey()) || entry.getKey().contains(key))
			{
				return entry.getValue();
			}
		}

		return null;
	}

	static String normalizeTaskKey(String name)
	{
		return name.toLowerCase(Locale.ROOT).replaceAll("[^a-z0-9]+", "");
	}

	private static boolean isIgnorableChoiceText(String text)
	{
		final String lower = text.toLowerCase(Locale.ROOT);
		return lower.equals("slayer task choice")
			|| lower.startsWith("amount")
			|| lower.startsWith("complete ")
			|| lower.contains("unlock a third choice")
			|| lower.matches("\\d+\\s+to\\s+\\d+")
			|| lower.matches("\\+\\d+.*")
			|| lower.contains("clue chance")
			|| lower.contains("slayer points")
			|| lower.contains("slayer xp")
			|| lower.contains("task quantity");
	}

	private static boolean looksLikeCreatureName(String text)
	{
		if (text.length() < 3 || text.length() > 40)
		{
			return false;
		}
		if (!Character.isLetter(text.charAt(0)))
		{
			return false;
		}
		// Reject pure modifier / amount fragments already handled above.
		return !text.contains("%") && !text.contains("+");
	}

	static List<String> copyNonBlank(List<String> texts)
	{
		if (texts == null || texts.isEmpty())
		{
			return Collections.emptyList();
		}
		final List<String> copy = new ArrayList<>();
		for (String text : texts)
		{
			if (text != null && !text.trim().isEmpty())
			{
				copy.add(text.trim());
			}
		}
		return copy;
	}
}

package com.superiorslayertracker;

import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.Getter;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.VarbitChanged;
import net.runelite.api.events.WidgetLoaded;
import net.runelite.api.gameval.VarPlayerID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.util.Text;

/**
 * Tracks Mortimer "Superior unique chance" task modifiers from the choice UI
 * and assignment dialog, then exposes the active bonus for superior kill logs.
 */
@Slf4j
@Singleton
public class TaskModifierTracker
{
	/** Mortimer Slayer Task Choice interface (from live probe). */
	static final int SLAYER_TASK_CHOICE_GROUP = 236;

	private static final String KEY_BONUS = "activeSuperiorUniqueBonus";
	private static final String KEY_TARGET = "activeSuperiorUniqueTaskTarget";

	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	@Inject
	private ConfigManager configManager;

	@Getter
	private Integer activeSuperiorUniqueBonus;

	private int activeTaskTarget = -1;
	private int lastCount = -1;
	private int lastTarget = -1;

	/**
	 * False after login/hop until {@link #reconcileAfterLogin()} runs. While false,
	 * slayer varp updates only refresh baselines and must not clear a restored bonus
	 * (target IDs can flicker while the client hydrates).
	 */
	private boolean slayerVarpsHydrated;

	private Map<String, Integer> choiceOffers = Map.of();
	/** True after a choice-UI read until the next task assignment consumes it. */
	private boolean pendingChoiceOffers;

	void loadPersistedState()
	{
		final Integer bonus = configManager.getConfiguration(
			SuperiorSlayerTrackerConfig.CONFIG_GROUP, KEY_BONUS, Integer.class);
		final Integer target = configManager.getConfiguration(
			SuperiorSlayerTrackerConfig.CONFIG_GROUP, KEY_TARGET, Integer.class);

		activeSuperiorUniqueBonus = bonus;
		activeTaskTarget = target != null ? target : -1;

		if (activeSuperiorUniqueBonus != null)
		{
			log.info("Restored superior unique bonus +{}% for task target {}",
				activeSuperiorUniqueBonus, activeTaskTarget);
		}

		// Plugin reload while already in-game never gets a fresh LOGGED_IN event.
		if (client.getGameState() == GameState.LOGGED_IN)
		{
			clientThread.invokeLater(() -> reconcileAfterLogin(0));
		}
	}

	void clear()
	{
		setActiveBonus(null, -1);
		clearPendingChoiceOffers();
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		final GameState state = event.getGameState();
		if (state == GameState.LOGIN_SCREEN || state == GameState.HOPPING)
		{
			// Keep persisted values; in-memory choice UI cache is session-only.
			clearPendingChoiceOffers();
			lastCount = -1;
			lastTarget = -1;
			slayerVarpsHydrated = false;
			return;
		}

		if (state == GameState.LOGGED_IN)
		{
			// Defer until varps are populated for this login.
			clientThread.invokeLater(() -> reconcileAfterLogin(0));
		}
	}

	/**
	 * After login/hop, adopt current slayer varps and only clear a restored bonus when
	 * the live task target clearly disagrees with what was saved.
	 */
	private void reconcileAfterLogin(int attempt)
	{
		if (client.getGameState() != GameState.LOGGED_IN)
		{
			return;
		}

		final int count = client.getVarpValue(VarPlayerID.SLAYER_COUNT);
		final int target = client.getVarpValue(VarPlayerID.SLAYER_TARGET);

		// Slayer varps stream in over the first ticks after login; 0/0 with a task on
		// the account usually means they simply haven't arrived yet. Wait before
		// judging, otherwise a restored bonus gets cleared against empty values.
		if (count == 0 && target == 0 && attempt < 10)
		{
			final int next = attempt + 1;
			clientThread.invokeLater(() -> reconcileAfterLogin(next));
			return;
		}

		lastCount = count;
		lastTarget = target;
		slayerVarpsHydrated = true;

		if (activeSuperiorUniqueBonus == null)
		{
			log.debug("Login reconcile: no active superior unique bonus (count={} target={})",
				count, target);
			return;
		}

		if (count > 0 && target > 0 && activeTaskTarget >= 0 && target != activeTaskTarget)
		{
			log.info(
				"Login reconcile: saved bonus target {} != current task target {}; clearing +{}%",
				activeTaskTarget, target, activeSuperiorUniqueBonus);
			setActiveBonus(null, -1);
			return;
		}

		log.info(
			"Login reconcile: keeping superior unique bonus +{}% (task target {}, count={})",
			activeSuperiorUniqueBonus, activeTaskTarget, count);
		persist();
	}

	@Subscribe
	public void onWidgetLoaded(WidgetLoaded event)
	{
		if (event.getGroupId() != SLAYER_TASK_CHOICE_GROUP)
		{
			return;
		}

		// Widgets may not be fully populated at the exact load event — refresh next client tick.
		clientThread.invokeLater(this::refreshChoiceOffers);
	}

	@Subscribe
	public void onChatMessage(ChatMessage event)
	{
		if (event.getType() != ChatMessageType.DIALOG && event.getType() != ChatMessageType.GAMEMESSAGE)
		{
			return;
		}

		final String msg = Text.removeTags(event.getMessage());
		if (msg == null || msg.isEmpty())
		{
			return;
		}

		final Integer dialogBonus = TaskModifierParser.parseSuperiorUniqueBonus(msg);
		final String assignedName = TaskModifierParser.parseAssignedTaskName(msg);

		if (assignedName == null && dialogBonus == null)
		{
			return;
		}

		if (dialogBonus != null)
		{
			final int target = client.getVarpValue(VarPlayerID.SLAYER_TARGET);
			setActiveBonus(dialogBonus, target);
			clearPendingChoiceOffers();
			log.info("Superior unique bonus +{}% from dialog (task={})", dialogBonus, assignedName);
			return;
		}

		// Assignment dialog without an inline superior % — resolve from choice UI cache.
		if (assignedName != null)
		{
			applyOfferForTask(assignedName);
		}
	}

	@Subscribe
	public void onVarbitChanged(VarbitChanged event)
	{
		final int varpId = event.getVarpId();
		if (varpId != VarPlayerID.SLAYER_COUNT && varpId != VarPlayerID.SLAYER_TARGET)
		{
			return;
		}

		final int count = client.getVarpValue(VarPlayerID.SLAYER_COUNT);
		final int target = client.getVarpValue(VarPlayerID.SLAYER_TARGET);

		// Until login reconcile finishes, only track baselines — never clear restored state.
		if (!slayerVarpsHydrated)
		{
			lastCount = count;
			lastTarget = target;
			return;
		}

		final boolean taskEnded = lastCount > 0 && count == 0;
		// Same-monster reassignment (e.g. cape cancel → same task) bumps count without
		// changing SLAYER_TARGET, so treat a count increase as a new task too.
		final boolean targetChanged = target != lastTarget;
		final boolean countIncreased = count > lastCount;
		final boolean taskStarted = count > 0
			&& (lastCount <= 0 || targetChanged || countIncreased);
		final boolean assignmentSettling = lastCount > 0 && count == lastCount && targetChanged;

		lastCount = count;
		lastTarget = target;

		if (taskEnded)
		{
			// Keep the bonus after count hits 0 so a superior that spawned on the last
			// kill still records the Mortimer modifier when looted.
			log.info("Slayer task cleared; retaining superior unique bonus until next task");
			return;
		}

		if (!taskStarted)
		{
			// Ignore target clearing to 0 (task complete). Only drop the bonus when the
			// game points at a different live task without going through taskStarted.
			if (activeSuperiorUniqueBonus != null && activeTaskTarget >= 0
				&& target > 0 && target != activeTaskTarget)
			{
				log.info(
					"Slayer target changed to {} while bonus bound to {}; clearing +{}%",
					target, activeTaskTarget, activeSuperiorUniqueBonus);
				setActiveBonus(null, -1);
			}
			return;
		}

		// New task with a different monster: drop the previous bonus — unless a sole
		// choice-UI offer is still pending, or COUNT/TARGET are still settling on the
		// same assignment (separate ticks). Premature clear + clearPending caused
		// Banshees +70% to be wiped before the assignment dialog could match.
		final boolean solePendingOffer = pendingChoiceOffers && choiceOffers.size() == 1;
		if (activeSuperiorUniqueBonus != null && activeTaskTarget >= 0 && activeTaskTarget != target
			// target 0 means SLAYER_TARGET hasn't arrived/settled yet (varps stream in
			// one at a time) — never treat that as a different task.
			&& target > 0)
		{
			if (solePendingOffer || assignmentSettling)
			{
				activeTaskTarget = target;
				persist();
			}
			else
			{
				log.info("New slayer task; clearing previous superior unique bonus");
				setActiveBonus(null, -1);
			}
		}

		// Backup while varps settle; leave pendingChoiceOffers for the dialog to confirm.
		if (activeSuperiorUniqueBonus == null && solePendingOffer)
		{
			final Integer only = choiceOffers.values().iterator().next();
			setActiveBonus(only, target);
			log.info("Superior unique bonus +{}% from sole choice-UI offer (pending dialog confirm)", only);
		}
		else if (activeSuperiorUniqueBonus != null && activeTaskTarget < 0)
		{
			activeTaskTarget = target;
			persist();
		}
	}

	private void applyOfferForTask(String taskName)
	{
		final int target = client.getVarpValue(VarPlayerID.SLAYER_TARGET);

		if (pendingChoiceOffers)
		{
			final Integer bonus = TaskModifierParser.lookupOffer(choiceOffers, taskName);
			setActiveBonus(bonus, target);
			clearPendingChoiceOffers();
			if (bonus != null)
			{
				log.info("Superior unique bonus +{}% matched choice UI offer for {}", bonus, taskName);
			}
			else
			{
				log.info("Task '{}' has no superior unique choice offer; bonus cleared", taskName);
			}
			return;
		}

		// No choice UI this assignment (e.g. cape reassign) — do not keep a stale bonus.
		setActiveBonus(null, target);
		log.info("Task '{}' assigned without choice-UI offers; superior unique bonus cleared", taskName);
	}

	private void refreshChoiceOffers()
	{
		final List<String> texts = new ArrayList<>();
		collectTexts(client.getWidget(SLAYER_TASK_CHOICE_GROUP, 0), texts, 0);
		if (texts.isEmpty())
		{
			return;
		}

		// Keep offers until assignment consumes them — players often sit on the
		// choice screen longer than a short TTL (dialog % is often omitted).
		choiceOffers = TaskModifierParser.parseChoiceOffers(texts);
		pendingChoiceOffers = true;
		if (!choiceOffers.isEmpty())
		{
			log.info("Cached superior unique choice offers: {}", choiceOffers);
		}
		else
		{
			log.debug("Slayer Task Choice opened with no superior unique offers (texts={})", texts.size());
		}
	}

	private void clearPendingChoiceOffers()
	{
		choiceOffers = Map.of();
		pendingChoiceOffers = false;
	}

	private void collectTexts(Widget widget, List<String> out, int depth)
	{
		if (widget == null || depth > 16)
		{
			return;
		}

		final String text = widget.getText();
		if (text != null && !text.isEmpty())
		{
			out.add(Text.removeTags(text));
		}

		collectChildren(widget.getDynamicChildren(), out, depth);
		collectChildren(widget.getStaticChildren(), out, depth);
		collectChildren(widget.getNestedChildren(), out, depth);
	}

	private void collectChildren(Widget[] children, List<String> out, int depth)
	{
		if (children == null)
		{
			return;
		}
		for (Widget child : children)
		{
			collectTexts(child, out, depth + 1);
		}
	}

	private void setActiveBonus(Integer bonus, int taskTarget)
	{
		activeSuperiorUniqueBonus = bonus;
		activeTaskTarget = bonus == null ? -1 : taskTarget;
		persist();
	}

	private void persist()
	{
		if (activeSuperiorUniqueBonus == null)
		{
			configManager.unsetConfiguration(SuperiorSlayerTrackerConfig.CONFIG_GROUP, KEY_BONUS);
			configManager.unsetConfiguration(SuperiorSlayerTrackerConfig.CONFIG_GROUP, KEY_TARGET);
		}
		else
		{
			configManager.setConfiguration(
				SuperiorSlayerTrackerConfig.CONFIG_GROUP, KEY_BONUS, activeSuperiorUniqueBonus);
			configManager.setConfiguration(
				SuperiorSlayerTrackerConfig.CONFIG_GROUP, KEY_TARGET, activeTaskTarget);
		}

		// ConfigManager otherwise only flushes ~every 5 minutes / on clean shutdown.
		// Force a write so force-kills don't lose the active Mortimer bonus.
		configManager.sendConfig();
	}
}

