package com.superiorslayertracker;

import java.util.Arrays;
import java.util.List;
import java.util.Map;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

public class TaskModifierParserTest
{
	@Test
	public void parsesSuperiorUniqueBonusFromUiText()
	{
		assertEquals(Integer.valueOf(280),
			TaskModifierParser.parseSuperiorUniqueBonus("+280% Superior unique chance"));
		assertEquals(Integer.valueOf(55),
			TaskModifierParser.parseSuperiorUniqueBonus("55% Superior unique chance"));
		assertNull(TaskModifierParser.parseSuperiorUniqueBonus("+105% Clue chance"));
		assertNull(TaskModifierParser.parseSuperiorUniqueBonus("+10 Slayer points"));
	}

	@Test
	public void parsesAssignedTaskNameFromDialog()
	{
		assertEquals("Crawling Hands", TaskModifierParser.parseAssignedTaskName(
			"Mortimer|Excellent, you're doing great. Your new task is to kill 38 Crawling Hands. "
				+ "Completing this task will award 10 bonus Slayer Points."));
		assertEquals("Basilisks", TaskModifierParser.parseAssignedTaskName(
			"Your new task is to kill 52 Basilisks. Completing this task will grant +280% Superior unique chance."));
	}

	@Test
	public void parsesChoiceOffersFromOrderedWidgetTexts()
	{
		final List<String> texts = Arrays.asList(
			"Slayer Task Choice",
			"Cave Horrors",
			"Amount",
			"80 to 120",
			"+55% Slayer XP",
			"Basilisks",
			"Amount",
			"40 to 60",
			"+280% Superior unique chance",
			"Venators",
			"Amount",
			"120 to 180",
			"+145% Clue chance",
			"Complete 50 tasks with Mortimer to unlock a third choice.");

		final Map<String, Integer> offers = TaskModifierParser.parseChoiceOffers(texts);
		assertEquals(1, offers.size());
		assertEquals(Integer.valueOf(280), offers.get(TaskModifierParser.normalizeTaskKey("Basilisks")));
		assertEquals(Integer.valueOf(280), TaskModifierParser.lookupOffer(offers, "Basilisks"));
		assertNull(TaskModifierParser.lookupOffer(offers, "Cave Horrors"));
	}

	@Test
	public void normalizeTaskKeyStripsNoise()
	{
		assertEquals("crawlinghands", TaskModifierParser.normalizeTaskKey("Crawling Hands"));
		assertTrue(TaskModifierParser.normalizeTaskKey("Blood-starved venators")
			.contains("venator"));
	}
}

package com.superiorslayertracker;

import com.google.gson.Gson;
import java.util.ArrayList;
import java.util.List;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;

public class LootTrackerImportLogicTest
{
	@Test
	public void killsToImportUsesDelta()
	{
		assertEquals(10, LootTrackerImportLogic.killsToImport(10, 0));
		assertEquals(5, LootTrackerImportLogic.killsToImport(10, 5));
		assertEquals(0, LootTrackerImportLogic.killsToImport(10, 10));
		assertEquals(0, LootTrackerImportLogic.killsToImport(10, 12));
	}

	@Test
	public void parsesLootTrackerNpcAggregateJson()
	{
		final String json = "{\"type\":\"NPC\",\"name\":\"Crushing hand\",\"kills\":1,"
			+ "\"first\":1785531800556,\"last\":1785531800555,\"drops\":[526,1,2942,1]}";
		final LootTrackerNpcAggregate aggregate = new Gson().fromJson(json, LootTrackerNpcAggregate.class);
		assertNotNull(aggregate);
		assertEquals("Crushing hand", aggregate.getName());
		assertEquals(1, aggregate.getKills());
		assertEquals(1785531800555L, aggregate.getLast());
	}

	@Test
	public void stableIdsAreDeterministicAndPrefixed()
	{
		final String id = LootTrackerImportLogic.stableId("AA-PhHUU", "Abhorrent spectre", 3);
		assertEquals("loottracker:AA-PhHUU:abhorrentspectre:3", id);
		assertTrue(LootTrackerImportLogic.isImportStubId(id));
		assertFalse(LootTrackerImportLogic.isImportStubId("uuid-here"));
	}

	@Test
	public void buildStubsContinueIndexAfterExistingImports()
	{
		final List<SuperiorKill> stubs = LootTrackerImportLogic.buildStubs(
			"profile",
			123L,
			SuperiorMonster.ABHORRENT_SPECTRE,
			2,
			5,
			999L
		);

		assertEquals(2, stubs.size());
		assertEquals("loottracker:profile:abhorrentspectre:5", stubs.get(0).getUniqueID());
		assertEquals("loottracker:profile:abhorrentspectre:6", stubs.get(1).getUniqueID());
		assertEquals(999L, stubs.get(0).getTimestamp());
		assertEquals(null, stubs.get(0).getSuperiorDropRateModifier());
		assertTrue(stubs.get(0).getLoot().isEmpty());
	}

	@Test
	public void countsLiveAndImportKillsSeparately()
	{
		final List<SuperiorKill> kills = new ArrayList<>();
		kills.add(liveKill("Abhorrent spectre"));
		kills.add(stubKill("Abhorrent spectre", 0));
		kills.add(stubKill("Abhorrent spectre", 1));
		kills.add(liveKill("Nechryarch"));

		assertEquals(3, LootTrackerImportLogic.countMonsterKills(kills, SuperiorMonster.ABHORRENT_SPECTRE));
		assertEquals(2, LootTrackerImportLogic.countImportStubs(kills, SuperiorMonster.ABHORRENT_SPECTRE));
		assertEquals(1, LootTrackerImportLogic.countMonsterKills(kills, SuperiorMonster.NECHRYARCH));
		assertEquals(0, LootTrackerImportLogic.countImportStubs(kills, SuperiorMonster.NECHRYARCH));
	}

	private static SuperiorKill liveKill(String name)
	{
		final SuperiorKill kill = new SuperiorKill();
		kill.setUniqueID("live-" + name);
		kill.setMonsterName(name);
		return kill;
	}

	private static SuperiorKill stubKill(String name, int index)
	{
		final SuperiorKill kill = new SuperiorKill();
		kill.setUniqueID(LootTrackerImportLogic.stableId("profile", name, index));
		kill.setMonsterName(name);
		return kill;
	}
}

