package com.superiorslayertracker;

import org.junit.Test;

import static org.junit.Assert.assertEquals;

public class HeartExpectationTest
{
	private static final double EPS = 1e-9;

	@Test
	public void unmodifiedKillUsesBaseRate()
	{
		assertEquals(1.0d, HeartExpectation.uniqueTableMultiplier(null), EPS);
		assertEquals(1.0d, HeartExpectation.uniqueTableMultiplier(0), EPS);
		assertEquals(
			1.0d / SuperiorMonster.DREADBORN_ARAXYTE.getHeartRarityDenominator(),
			HeartExpectation.expectedHeartsFromKill(SuperiorMonster.DREADBORN_ARAXYTE, null),
			EPS
		);
	}

	@Test
	public void mortimerBonusScalesUniqueTableAccess()
	{
		// +300% → 4× the base chance: Night Beast 1/256 → 1/64
		assertEquals(4.0d, HeartExpectation.uniqueTableMultiplier(300), EPS);
		assertEquals(
			256.0d / 4.0d,
			HeartExpectation.effectiveHeartDenominator(SuperiorMonster.NIGHT_BEAST, 300),
			EPS
		);
		assertEquals(
			4.0d / SuperiorMonster.NIGHT_BEAST.getHeartRarityDenominator(),
			HeartExpectation.expectedHeartsFromKill(SuperiorMonster.NIGHT_BEAST, 300),
			EPS
		);

		// +275% → 3.75×
		assertEquals(3.75d, HeartExpectation.uniqueTableMultiplier(275), EPS);
		assertEquals(
			3.75d / SuperiorMonster.ABHORRENT_SPECTRE.getHeartRarityDenominator(),
			HeartExpectation.expectedHeartsFromKill(SuperiorMonster.ABHORRENT_SPECTRE, 275),
			EPS
		);

		// +80% must be an increase (1.8×), never a reduction
		assertEquals(1.8d, HeartExpectation.uniqueTableMultiplier(80), EPS);
	}

	@Test
	public void effectiveWeightMatchesMultiplier()
	{
		assertEquals(1.0d, HeartExpectation.effectiveKillWeight(null), EPS);
		assertEquals(4.0d, HeartExpectation.effectiveKillWeight(300), EPS);
		assertEquals(1.8d, HeartExpectation.effectiveKillWeight(80), EPS);
	}
}
